import React, { useState, useEffect, useRef } from 'react';
import { Button, Typography, Grid, Paper, Box, CircularProgress } from '@mui/material';

const AdminViewWork = () => {
  const [woItems, setWoItems] = useState([]);
  const [selectedItem, setSelectedItem] = useState(null);
  const [popupVisible, setPopupVisible] = useState(false);
  const [loading, setLoading] = useState(true);
  const popupRef = useRef(null);

  useEffect(() => {
    fetchWOItems();
  }, []);

  const fetchWOItems = async () => {
    try {
      setLoading(true);
      const response = await fetch('http://localhost:8080/worker/getwoitems');
      const data = await response.json();

      // Sort by date, newest first
      const sortedData = data.sort((a, b) => {
        return new Date(b.date) - new Date(a.date);
      });

      setWoItems(sortedData);
    } catch (error) {
      console.error('Error fetching WOItems:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleCardClick = (item) => {
    setSelectedItem(item);
    setPopupVisible(true);
  };

  const handleClosePopup = () => {
    setPopupVisible(false);
    setSelectedItem(null);
  };

  const handleDeleteWorkOrder = async () => {
    if (!selectedItem) return;

    const confirmDelete = window.confirm(`Are you sure you want to delete Work Order Number: ${selectedItem.fileNumber}?`);
    if (!confirmDelete) return;

    try {
      const response = await fetch(`http://localhost:8080/worker/delete/${selectedItem.id}`, {
        method: 'DELETE',
      });

      if (response.ok) {
        alert('Work Order deleted successfully.');
        handleClosePopup();
        fetchWOItems(); // Refresh the grid
      } else {
        alert('Failed to delete Work Order.');
      }
    } catch (error) {
      console.error('Error deleting Work Order:', error);
      alert('An error occurred while deleting the Work Order.');
    }
  };

  useEffect(() => {
    if (popupVisible) {
      const handleClickOutside = (event) => {
        if (popupRef.current && !popupRef.current.contains(event.target)) {
          handleClosePopup();
        }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => {
        document.removeEventListener('mousedown', handleClickOutside);
      };
    }
  }, [popupVisible]);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '70vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" sx={{ fontWeight: 'bold', textAlign: 'center', mb: 4 }}>
        Completed Work Orders
      </Typography>

      {woItems.length === 0 ? (
        <Typography variant="body1" align="center" sx={{ mt: 4 }}>
          No completed work orders found.
        </Typography>
      ) : (
        <Grid container spacing={2}>
          {woItems.map((woItem) => (
            <Grid item xs={12} sm={6} md={4} lg={2} key={woItem.id}>
              <Paper
                elevation={3}
                sx={{ 
                  p: 2, 
                  textAlign: 'center', 
                  cursor: 'pointer',
                  height: '100%',
                  display: 'flex',
                  flexDirection: 'column',
                  justifyContent: 'center',
                  '&:hover': { backgroundColor: '#f0f0f0' }
                }}
                onClick={() => handleCardClick(woItem)}
              >
                <Typography variant="h6" sx={{ mb: 1 }}>{woItem.name}</Typography>
                <Typography variant="body2">Work Order: {woItem.fileNumber}</Typography>
                <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                  {new Date(woItem.date).toLocaleDateString()}
                </Typography>
              </Paper>
            </Grid>
          ))}
        </Grid>
      )}

      {popupVisible && selectedItem && (
        <div
          className="popup-overlay"
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            width: '100vw',
            height: '100vh',
            backgroundColor: 'rgba(0,0,0,0.5)',
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            zIndex: 1000,
          }}
        >
          <div
            ref={popupRef}
            className="popup-content"
            style={{
              backgroundColor: '#fff',
              padding: '30px',
              borderRadius: '10px',
              width: '500px',
              maxHeight: '90vh',
              overflowY: 'auto',
              textAlign: 'left'
            }}
          >
            <Typography variant="h4" gutterBottom sx={{ textAlign: 'center' }}>
              {selectedItem.name}
            </Typography>

            <Box sx={{ mb: 3 }}>
              <Typography variant="h6" gutterBottom>Work Order Details</Typography>
              <Grid container spacing={2}>
                <Grid item xs={6}>
                  <Typography><strong>Work Order:</strong></Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography>{selectedItem.fileNumber}</Typography>
                </Grid>

                <Grid item xs={6}>
                  <Typography><strong>Company:</strong></Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography>{selectedItem.company}</Typography>
                </Grid>

                <Grid item xs={6}>
                  <Typography><strong>Price:</strong></Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography>${selectedItem.myPrice}</Typography>
                </Grid>

                <Grid item xs={6}>
                  <Typography><strong>SBA Total:</strong></Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography>${selectedItem.sBATotal}</Typography>
                </Grid>

                <Grid item xs={6}>
                  <Typography><strong>Plat:</strong></Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography>{selectedItem.plat ? "Yes" : "No"}</Typography>
                </Grid>

                <Grid item xs={6}>
                  <Typography><strong>Assessment:</strong></Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography>{selectedItem.assessment}</Typography>
                </Grid>

                <Grid item xs={6}>
                  <Typography><strong>Address:</strong></Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography>{selectedItem.address}</Typography>
                </Grid>

                <Grid item xs={6}>
                  <Typography><strong>Date:</strong></Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography>{new Date(selectedItem.date).toLocaleDateString()}</Typography>
                </Grid>
              </Grid>
            </Box>

            <Box sx={{ mb: 2 }}>
              <Typography variant="h6" gutterBottom>Comments</Typography>
              <Typography>{selectedItem.comments || "No comments provided."}</Typography>
            </Box>

            <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 4 }}>
              <Button
                onClick={handleClosePopup}
                sx={{ color: 'blue', textDecoration: 'underline' }}
              >
                Close
              </Button>

              <Button
                onClick={handleDeleteWorkOrder}
                variant="contained"
                color="error"
              >
                Delete
              </Button>
            </Box>
          </div>
        </div>
      )}
    </Box>
  );
};

export default AdminViewWork;
